// Parsear el mensaje de WhatsApp (Twilio format)
const body = $input.item.json.body;

// Extraer información del mensaje
const from = body.From || body.from;
const message = body.Body || body.body || '';
const messageId = body.MessageSid || body.messageSid;

// Limpiar número de teléfono (remover 'whatsapp:')
const cleanPhone = from.replace('whatsapp:', '');

return [{
  json: {
    from: cleanPhone,
    message: message.trim(),
    messageId: messageId,
    timestamp: new Date().toISOString()
  }
}];

// Mapeo de números de teléfono a league_id
// TODO: Reemplazar con tus IDs reales
const phoneToLeague = {
  '+521234567890': '12345678-1234-1234-1234-123456789012',  // Liga Elite
  '+529876543210': '87654321-4321-4321-4321-210987654321'   // Liga Amateur
};

const phoneNumber = $json.from;
const message = $json.message.toLowerCase();

// Detectar liga desde el mensaje si menciona el nombre
let leagueId = phoneToLeague[phoneNumber];

if (message.includes('elite') || message.includes('liga 1')) {
  leagueId = '12345678-1234-1234-1234-123456789012';
} else if (message.includes('amateur') || message.includes('liga 2')) {
  leagueId = '87654321-4321-4321-4321-210987654321';
}

// Si no se encontró liga, usar una por defecto
if (!leagueId) {
  leagueId = '12345678-1234-1234-1234-123456789012'; // Default
}

return [{
  json: {
    ...($json),
    league_id: leagueId
  }
}];

// Detectar comandos rápidos (sin usar IA)
const message = $json.message.toLowerCase().trim();

// Comandos de ayuda
if (message === 'menu' || message === 'ayuda' || message === 'help') {
  return [{
    json: {
      quick_reply: true,
      response: `🤖 *COMANDOS DISPONIBLES*\n\n📅 "partidos" - Jornada de la semana\n🏆 "tabla" - Tabla de posiciones\n🚫 "suspendidos" - Jugadores suspendidos\n⚽ "resultados" - Últimos resultados\n📊 "goleadores" - Tabla de goleadores\n\n💬 O simplemente pregúntame lo que quieras saber sobre la liga!`
    }
  }];
}

// Si no es comando rápido, continuar con IA
return [{
  json: {
    quick_reply: false,
    ...$json
  }
}];

// Preparar embedding para Supabase
const embedding = $json.data[0].embedding;
const embeddingString = '[' + embedding.join(',') + ']';

const previousData = $('Detect League Context').item.json;

return [{
  json: {
    query_embedding: embeddingString,
    league_id: previousData.league_id,
    user_message: previousData.message,
    from: previousData.from
  }
}];

// Obtener todos los resultados de búsqueda
const searchResults = $input.all();
const userData = $('Prepare Vector Search').item.json;

// Si no hay resultados, usar mensaje por defecto
if (!searchResults || searchResults.length === 0) {
  return [{
    json: {
      system_prompt: 'Eres un asistente de WhatsApp para una liga de fútbol. No tienes información disponible en este momento. Discúlpate amablemente y sugiere que el usuario haga una pregunta diferente o contacte al administrador de la liga.',
      user_message: userData.user_message,
      from: userData.from,
      has_context: false
    }
  }];
}

// Concatenar resultados de búsqueda como contexto
const context = searchResults
  .filter(item => item.json.similarity > 0.7) // Solo resultados con alta similitud
  .map(item => `${item.json.content_text}\n(Relevancia: ${Math.round(item.json.similarity * 100)}%)`)
  .join('\n\n---\n\n');

const systemPrompt = `Eres un asistente de WhatsApp para una liga de fútbol amateur/profesional.

USA LA SIGUIENTE INFORMACIÓN para responder la pregunta del usuario:

${context}

INSTRUCCIONES:
- Responde SOLO basándote en la información proporcionada
- Sé conciso (máximo 3 párrafos cortos)
- Usa emojis cuando sea apropiado (⚽🏆📅🚫👏)
- Si la información no está en el contexto, di que no la tienes disponible
- Mantén un tono amigable y profesional
- Responde en español
- Si hay múltiples respuestas relevantes, prioriza la más reciente
- Formatea la respuesta para WhatsApp (saltos de línea, negritas con *texto*)`;

return [{
  json: {
    system_prompt: systemPrompt,
    user_message: userData.user_message,
    from: userData.from,
    has_context: true,
    num_results: searchResults.length
  }
}];

// Preparar mensaje para enviar
const gptResponse = $json.choices[0].message.content;
const previousData = $('Build GPT Context').item.json;

return [{
  json: {
    to: `whatsapp:${previousData.from}`,
    body: gptResponse
  }
}];

// Enviar respuesta rápida directamente
const quickReply = $json.response;
const previousData = $('Parse WhatsApp Message').item.json;

return [{
  json: {
    to: `whatsapp:${previousData.from}`,
    body: quickReply
  }
}];
